"use strict";(self.webpackChunkhudi=self.webpackChunkhudi||[]).push([[88228],{28453:(e,a,t)=>{t.d(a,{R:()=>r,x:()=>o});var n=t(96540);const i={},s=n.createContext(i);function r(e){const a=n.useContext(s);return n.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function o(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),n.createElement(s.Provider,{value:a},e.children)}},47270:e=>{e.exports=JSON.parse('{"permalink":"/blog/2026/08/06/hudi-vs-iceberg-for-cdc-workloads","editUrl":"https://github.com/apache/hudi/edit/asf-site/website/blog/blog/2026-08-06-hudi-vs-iceberg-for-cdc-workloads.md","source":"@site/blog/2026-08-06-hudi-vs-iceberg-for-cdc-workloads.md","title":"Apache Hudi vs Apache Iceberg for CDC Workloads","description":"Hudi vs Iceberg for CDC: how each handles record lookups, deletes, small files, ordering and change streams \u2014 and a framework for choosing between them.","date":"2026-08-06T00:00:00.000Z","tags":[{"inline":true,"label":"comparison","permalink":"/blog/tags/comparison"},{"inline":true,"label":"apache iceberg","permalink":"/blog/tags/apache-iceberg"},{"inline":true,"label":"cdc","permalink":"/blog/tags/cdc"},{"inline":true,"label":"data lakehouse","permalink":"/blog/tags/data-lakehouse"}],"readingTime":13.85,"hasTruncateMarker":true,"authors":[{"name":"Sivabalan Narayanan","url":"https://www.linkedin.com/in/sivabalan-narayanan-1040b45/","imageURL":"/assets/images/authors/sivabalan.jpg","key":"sivabalan","page":null}],"frontMatter":{"title":"Apache Hudi vs Apache Iceberg for CDC Workloads","excerpt":"A mechanism-level comparison of how Apache Hudi and Apache Iceberg handle change data capture: record lookup, deletes, small files, ordering and change streams.","description":"Hudi vs Iceberg for CDC: how each handles record lookups, deletes, small files, ordering and change streams \u2014 and a framework for choosing between them.","authors":["sivabalan"],"category":"deep-dive","image":"/assets/images/blog/2024-12-03-apache-iceberg-vs-apache-hudi.jpeg","tags":["comparison","apache iceberg","cdc","data lakehouse"]},"unlisted":false,"lastUpdatedAt":1786026027000,"prevItem":{"title":"Apache Hudi vs Apache Iceberg for Streaming Ingestion","permalink":"/blog/2026/08/11/hudi-vs-iceberg-for-streaming-ingestion"},"nextItem":{"title":"Migrating from Apache Iceberg to Apache Hudi","permalink":"/blog/2026/08/05/migrating-from-apache-iceberg-to-hudi"}}')},59155:(e,a,t)=>{t.r(a),t.d(a,{assets:()=>d,contentTitle:()=>o,default:()=>h,frontMatter:()=>r,metadata:()=>n,toc:()=>l});var n=t(47270),i=t(74848),s=t(28453);const r={title:"Apache Hudi vs Apache Iceberg for CDC Workloads",excerpt:"A mechanism-level comparison of how Apache Hudi and Apache Iceberg handle change data capture: record lookup, deletes, small files, ordering and change streams.",description:"Hudi vs Iceberg for CDC: how each handles record lookups, deletes, small files, ordering and change streams \u2014 and a framework for choosing between them.",authors:["sivabalan"],category:"deep-dive",image:"/assets/images/blog/2024-12-03-apache-iceberg-vs-apache-hudi.jpeg",tags:["comparison","apache iceberg","cdc","data lakehouse"]},o=void 0,d={authorsImageUrls:[void 0]},l=[{value:"What CDC demands from a table format",id:"what-cdc-demands-from-a-table-format",level:2},{value:"Finding the record: indexes vs. joins",id:"finding-the-record-indexes-vs-joins",level:2},{value:"How deletes actually work",id:"how-deletes-actually-work",level:2},{value:"Commit frequency and small files",id:"commit-frequency-and-small-files",level:2},{value:"Ordering, dedup and partial updates",id:"ordering-dedup-and-partial-updates",level:2},{value:"Producing change streams downstream",id:"producing-change-streams-downstream",level:2},{value:"Operational reality",id:"operational-reality",level:2},{value:"A decision framework",id:"a-decision-framework",level:2},{value:"It&#39;s Not Either/Or: Interoperability via Apache XTable",id:"its-not-eitheror-interoperability-via-apache-xtable",level:2},{value:"Conclusion",id:"conclusion",level:2},{value:"FAQ",id:"faq",level:2}];function c(e){const a={a:"a",code:"code",em:"em",h2:"h2",li:"li",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components},{PostFAQ:t}=a;return t||function(e,a){throw new Error("Expected "+(a?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("PostFAQ",!0),(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(a.p,{children:"Both Apache Hudi and Apache Iceberg can ingest change data capture (CDC) streams, but they were designed around different problems. Hudi was built for mutation-heavy ingestion: a record-level index that locates any key without scanning the table, merge-on-read delta logs that absorb frequent updates and deletes cheaply, and built-in deduplication, ordering and file sizing. Iceberg was designed first for large, reliable analytical scans; its copy-on-write and delete-file-based merge-on-read paths make row-level mutations possible, but high-frequency CDC merges are more expensive to plan, execute and maintain. This post walks through the mechanisms behind that difference \u2014 record lookup, delete handling, commit frequency, ordering and change streams \u2014 so you can judge the trade-offs against your own workload rather than take anyone's word for it."}),"\n",(0,i.jsx)(a.h2,{id:"what-cdc-demands-from-a-table-format",children:"What CDC demands from a table format"}),"\n",(0,i.jsxs)(a.p,{children:["A CDC stream is, by construction, mostly mutations. If you replicate an operational database to the lake (the basics are covered in ",(0,i.jsx)(a.a,{href:"/blog/2026/07/22/what-is-cdc-on-a-data-lake",children:"What is CDC on a Data Lake?"})," and the deeper ",(0,i.jsx)(a.a,{href:"/blog/2024/07/30/data-lake-cdc",children:"Understanding Data Lake Change Data Capture"}),"), the table format underneath has to sustain a specific set of pressures:"]}),"\n",(0,i.jsxs)(a.ul,{children:["\n",(0,i.jsxs)(a.li,{children:[(0,i.jsx)(a.strong,{children:"Fast key-based upserts and deletes."})," Every change event targets one row identified by a primary key. The write path must find where that key lives and apply the change without rewriting or rescanning unrelated data."]}),"\n",(0,i.jsxs)(a.li,{children:[(0,i.jsx)(a.strong,{children:"Ordering and late data."})," Events arrive out of order after retries and repartitioning. The format must merge by the source's log position or event time, not arrival time, or the table silently regresses."]}),"\n",(0,i.jsxs)(a.li,{children:[(0,i.jsx)(a.strong,{children:"Frequent small commits."})," Minute-level freshness means committing every few minutes, around the clock. That stresses metadata, file counts and any background maintenance."]}),"\n",(0,i.jsxs)(a.li,{children:[(0,i.jsx)(a.strong,{children:"Change streams for downstream consumers."})," Bronze tables that absorb CDC should also ",(0,i.jsx)(a.em,{children:"emit"})," changes, so silver and gold tables can be built incrementally instead of re-reading everything."]}),"\n"]}),"\n",(0,i.jsx)(a.p,{children:"Hold each format against these four demands and the architectural differences become concrete."}),"\n",(0,i.jsx)(a.h2,{id:"finding-the-record-indexes-vs-joins",children:"Finding the record: indexes vs. joins"}),"\n",(0,i.jsx)(a.p,{children:'The first job in applying an upsert is answering "which file contains this key?"'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Hudi"})," treats indexing as a core component of the write path. Every record key maps to exactly one file group, and Hudi maintains ",(0,i.jsx)(a.a,{href:"/docs/indexes",children:"pluggable indexes"})," \u2014 bloom-filter, simple-join, bucket-hash and, since 0.14.0, a record-level index stored inside the table's metadata table \u2014 that resolve incoming keys to their file groups directly. With the record-level index, lookup cost is proportional to the number of records changed, not the size of the table: the writer consults hash-sharded key-to-location mappings, tags each incoming record with its target file group, and only touches those file groups. For merge-on-read tables this also bounds read cost, because a base file only ever needs to merge against log records belonging to that same file group. The same ",(0,i.jsx)(a.a,{href:"/docs/indexes#multi-modal-indexing",children:"multi-modal indexing subsystem"})," extends beyond keys \u2014 secondary indexes and expression indexes on non-key columns, borrowed straight from relational database design \u2014 which is one of the deeper architectural choices catalogued in ",(0,i.jsx)(a.a,{href:"/blog/2025/03/05/hudi-21-unique-differentiators",children:"21 unique differentiators of Apache Hudi"}),"."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Iceberg"})," deliberately has no record-level index; its metadata tree (manifests, partition values, column min/max stats) is built for pruning scans, not locating keys. A ",(0,i.jsx)(a.code,{children:"MERGE INTO"})," in Spark plans a join between the incoming batch and the target table to discover which files hold matching rows \u2014 column statistics can prune files, but for keys spread across a table the merge effectively scans and joins against much of it. Streaming writers such as Flink's Iceberg sink in upsert mode sidestep the lookup entirely by writing ",(0,i.jsx)(a.em,{children:"equality delete files"})," \u2014 \"delete any row where id = 5\" \u2014 which is cheap at write time precisely because nobody found the row. The cost doesn't disappear; it moves to every subsequent read and to compaction, which is the next section's subject."]}),"\n",(0,i.jsxs)(a.p,{children:["This difference is measurable, and you can reproduce it. In benchmarks run with the open-source ",(0,i.jsx)(a.a,{href:"https://github.com/onehouseinc/lake-loader",children:"LakeLoader framework"})," (Spark 3.5, Hudi 1.1.1, Iceberg 1.10.0), we observed Hudi delivering roughly 4\xd7 lower incremental write latency than Iceberg on a 10 TB partitioned table under skewed CDC-style updates \u2014 the record-level index shuffled around 250 MB per commit where the merge join shuffled hundreds of gigabytes \u2014 and roughly 8\xd7 lower steady-state latency on merge-on-read tables with sparse column-level updates. Run the framework against your own workload shape before trusting anyone's numbers, including these."]}),"\n",(0,i.jsx)(a.h2,{id:"how-deletes-actually-work",children:"How deletes actually work"}),"\n",(0,i.jsx)(a.p,{children:"Deletes are where CDC pipelines live or die, since every update in a changelog is logically a delete plus an insert of the new version."}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Hudi"})," logs a delete into the same file group where the key lives, exactly like an update. On a merge-on-read table this is an append to that file group's delta log; queries merge base file plus log at read time within the file group, and compaction later rewrites the base file with the deletes applied. Because deletes are colocated with the data they affect, the merge scope is always one base file against its own changes \u2014 never a table-wide reconciliation. Data locality is preserved by construction."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Iceberg"})," (format v2) represents row-level deletes as separate delete files of two kinds. ",(0,i.jsx)(a.em,{children:"Position deletes"})," name a row by data file path and row ordinal \u2014 precise and cheap to apply on read, but the writer must first find the row, which without an index means the join described above. ",(0,i.jsx)(a.em,{children:"Equality deletes"})," record column predicates and are cheap to write, but every reader must check each equality delete file against every data file with an older sequence number in its scan. When many data files and many delete files accumulate \u2014 the normal state of a high-frequency CDC stream \u2014 this approaches an N data files \xd7 M delete files reconciliation problem: query planning has to associate delete files with data files, and compaction jobs that merge them can balloon into runaway executions as both N and M grow between maintenance runs."]}),"\n",(0,i.jsxs)(a.p,{children:["The Iceberg community has been working on this. Format v3 replaces position delete files with binary ",(0,i.jsx)(a.em,{children:"deletion vectors"})," \u2014 at most one compact bitmap per data file \u2014 which removes much of the position-delete proliferation and read-time association cost, and engines are adopting it. But deletion vectors help the position-delete path; a writer still needs to determine which positions to delete, so the no-index lookup cost remains, and equality deletes still defer their cost to readers and compaction. The structural contrast stands: Iceberg records that a delete happened and reconciles later; Hudi routes the delete to where the record lives at write time."]}),"\n",(0,i.jsx)(a.h2,{id:"commit-frequency-and-small-files",children:"Commit frequency and small files"}),"\n",(0,i.jsx)(a.p,{children:"CDC means committing every few minutes, forever. Two things degrade under that regime: file sizes and metadata."}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Hudi"})," performs automatic file sizing during writes \u2014 small inserts are bin-packed into existing under-sized file groups, so frequent commits do not proliferate small files in the first place. Its cleaner bounds how many old file versions are retained, and timeline archival keeps the active timeline small, all running as managed table services alongside ingestion."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Iceberg"})," produces at least one new data file (and, in merge-on-read, delete files) plus a new snapshot per commit. Nothing in the write path resizes files, so a minute-level stream steadily accumulates small data files, delete files and snapshot metadata. The remedies exist \u2014 ",(0,i.jsx)(a.code,{children:"rewrite_data_files"})," for compaction, ",(0,i.jsx)(a.code,{children:"expire_snapshots"}),", ",(0,i.jsx)(a.code,{children:"rewrite_manifests"}),", ",(0,i.jsx)(a.code,{children:"rewrite_position_delete_files"})," \u2014 but they are maintenance procedures you schedule and size yourself, and under optimistic concurrency a long compaction can conflict with the streaming writer touching the same files and be forced to retry. The faster you commit, the faster maintenance debt accrues and the tighter that scheduling loop becomes."]}),"\n",(0,i.jsx)(a.h2,{id:"ordering-dedup-and-partial-updates",children:"Ordering, dedup and partial updates"}),"\n",(0,i.jsx)(a.p,{children:'Changelogs carry semantics beyond "latest write wins."'}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Hudi"})," requires a record key and supports an ordering (precombine) field as first-class table concepts. Multiple events for the same key within a batch are deduplicated by ordering value before write; a late-arriving event with an older ordering value than what's stored is dropped rather than applied, so out-of-order delivery cannot regress the table. Record merger and payload APIs go further: partial updates merge only the non-null incoming fields into the existing row, and custom merge logic (say, database-specific changelog semantics) can be plugged in. These behaviors were built for exactly the shape of a Debezium stream."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Iceberg"})," does not define keys, dedup or ordered merging at the format level \u2014 it stores what engines write. Spark's ",(0,i.jsx)(a.code,{children:"MERGE INTO"})," will fail if multiple source rows match one target row, so deduplication and event-time ordering must be implemented upstream in the pipeline; Flink's upsert mode assumes the stream itself is correctly ordered per key within its checkpoint discipline. That is a deliberate design choice \u2014 the format stays engine-neutral \u2014 but it means every CDC pipeline re-implements reconciliation logic the format doesn't provide."]}),"\n",(0,i.jsx)(a.h2,{id:"producing-change-streams-downstream",children:"Producing change streams downstream"}),"\n",(0,i.jsxs)(a.p,{children:["A CDC-fed bronze table is usually the head of a pipeline, so how each format ",(0,i.jsx)(a.em,{children:"emits"})," changes matters as much as how it absorbs them."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Hudi"})," keeps commit-time metadata on every record and supports ",(0,i.jsx)(a.a,{href:"/docs/table_types",children:"incremental queries"})," as a native query type: give a begin instant, get exactly the records that changed since, at any commit granularity. Since 0.13.0 a CDC query mode also returns database-style before/after images with the operation type, logged at write time. Downstream jobs chain these into incremental ETL, each layer consuming only deltas."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Iceberg"})," supports incremental scans between snapshots, which cover append-only snapshots; consuming row-level changes from snapshots that carry updates and deletes is harder, and Spark's ",(0,i.jsx)(a.code,{children:"create_changelog_view"})," procedure computes a changelog view by diffing snapshots \u2014 with pre/post images available as an optional, more expensive computation \u2014 rather than reading changes that were logged at write time. For append-mostly tables the two are comparable; for update-heavy tables, deriving the change stream costs more than reading one that was recorded as it happened."]}),"\n",(0,i.jsx)(a.h2,{id:"operational-reality",children:"Operational reality"}),"\n",(0,i.jsx)(a.p,{children:"What do you actually run in production?"}),"\n",(0,i.jsxs)(a.p,{children:["A Hudi ingestion job carries its table services with it: compaction, clustering, cleaning, file sizing and archival are scheduled and executed by the platform, inline or async, with ",(0,i.jsx)(a.a,{href:"/docs/concurrency_control",children:"MVCC coordinating writers and table services"})," so compaction does not block ingestion \u2014 plus non-blocking concurrency control (since 1.0) for multiple writers, and early conflict detection that aborts a doomed write mid-flight instead of at commit, saving the wasted compute. The ingestion job itself is often off-the-shelf: ",(0,i.jsx)(a.a,{href:"/docs/hoodie_streaming_ingestion",children:"Hudi Streamer"})," natively understands Debezium, AWS DMS and Mongo changelog formats and reads from Kafka, Pulsar, S3 and GCS, so a CDC pipeline can be a single command rather than custom Spark code. The knobs are there to tune, but the default posture is self-managing."]}),"\n",(0,i.jsx)(a.p,{children:"An Iceberg deployment composes the equivalent from parts: an orchestrator (or a managed catalog service) running compaction, snapshot expiry, delete-file rewrites and manifest rewrites at the right cadence for your commit rate, with conflict-retry behavior tuned so maintenance and streaming writers coexist. None of this is exotic, and managed platforms increasingly automate it \u2014 but on a high-frequency CDC table the maintenance cadence is unforgiving, and it is your pager when it falls behind."}),"\n",(0,i.jsx)(a.h2,{id:"a-decision-framework",children:"A decision framework"}),"\n",(0,i.jsx)(a.p,{children:"Honest summary rather than a scorecard:"}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Iceberg is a workable choice when"})," your CDC is low-frequency (hourly or slower batches), tables are append-mostly with modest update ratios, you already operate an Iceberg estate with maintenance automation in place, or organizational standardization on one format outweighs per-workload optimization. The v3 deletion-vector work also means the read-side delete overhead is shrinking release by release."]}),"\n",(0,i.jsxs)(a.p,{children:[(0,i.jsx)(a.strong,{children:"Hudi pulls ahead when"})," update/delete ratios are high (mirroring OLTP tables, not appending events), you need sub-hour freshness with commits every few minutes, keys are spread across the table so per-write lookup cost dominates, or downstream consumers need true record-level change streams. These are exactly the pressures Hudi's index, delta logs, precombine semantics and managed services were designed against."]}),"\n",(0,i.jsx)(a.h2,{id:"its-not-eitheror-interoperability-via-apache-xtable",children:"It's Not Either/Or: Interoperability via Apache XTable"}),"\n",(0,i.jsxs)(a.p,{children:["The framing of this post \u2014 pick one format \u2014 understates a practical third option. The formats' metadata layers describe data files; the data files themselves are Parquet either way. ",(0,i.jsx)(a.a,{href:"https://xtable.apache.org/",children:"Apache XTable"})," (incubating) exploits this by translating table metadata between Hudi, Iceberg and Delta Lake without copying data, so a single physical table can be read through more than one format's metadata."]}),"\n",(0,i.jsx)(a.p,{children:"For CDC specifically, that enables a concrete pattern: ingest with Hudi to get the record-level index, log-based deletes, auto file sizing and incremental queries on the write-heavy bronze layer, then run XTable to expose the same data as Iceberg metadata for engines and catalogs that only speak Iceberg \u2014 Snowflake, BigQuery, or an existing Iceberg-standardized analytics stack. The translation is incremental (it processes only new commits) and involves no data rewrite, since both formats point at the same Parquet files."}),"\n",(0,i.jsxs)(a.p,{children:["This decouples the write-path decision from the read-path decision. Choose the ingestion machinery on the merits of your CDC workload, and serve readers in whatever format they require. We cover the setup end-to-end in ",(0,i.jsx)(a.a,{href:"/blog/2026/07/28/using-hudi-with-apache-iceberg-via-xtable",children:"Using Hudi with Apache Iceberg via XTable"}),"."]}),"\n",(0,i.jsx)(a.h2,{id:"conclusion",children:"Conclusion"}),"\n",(0,i.jsx)(a.p,{children:"Hudi and Iceberg will both land a CDC stream. The difference is where the cost of mutation is paid. Hudi pays it at write time with machinery built for the purpose \u2014 an index that finds keys in O(changes), delta logs that keep deletes local to their file group, ordering and dedup in the format, file sizing and compaction as built-in services. Iceberg defers it \u2014 to read-time delete reconciliation, to maintenance jobs, to pipeline-level dedup logic \u2014 a trade that suits scan-heavy, append-mostly tables, and one that v3 continues to soften, but that compounds against you as update frequency rises. Map your workload's update ratio, freshness target and downstream consumption pattern onto those mechanisms, and the choice \u2014 or the XTable-enabled combination \u2014 usually makes itself."}),"\n",(0,i.jsx)(a.h2,{id:"faq",children:"FAQ"}),"\n",(0,i.jsx)(t,{heading:null,items:[{question:"Is Apache Iceberg good for CDC?",answer:"Iceberg can handle CDC, and it works well when changes arrive in low-frequency batches or tables are append-mostly. For high-frequency, update-heavy streams, the lack of a record-level index makes merges join against the table, delete files accumulate between compactions, and you must schedule maintenance jobs aggressively. Iceberg v3's deletion vectors improve the read-side cost, but the write-side lookup and maintenance burden remain."},{question:"Why is Hudi faster for upserts than Iceberg?",answer:"Hudi maintains indexes, including a record-level index, that map each record key directly to the file group holding it, so an upsert touches only the files that actually contain changed keys and lookup cost scales with the size of the change batch. Iceberg has no record index, so finding the rows to update requires joining the incoming batch against the target table. On merge-on-read tables Hudi also appends changes to delta logs instead of rewriting base files, deferring the rewrite to background compaction."},{question:"How do deletes differ between Hudi and Iceberg?",answer:"Hudi logs a delete into the same file group where the record lives, and compaction later applies it while rewriting that one base file, so merge scope stays local. Iceberg v2 writes separate position or equality delete files that readers and compaction jobs must reconcile against data files, a cost that grows as both accumulate. Iceberg v3 replaces position delete files with per-file deletion vectors, which meaningfully reduces the read-side overhead."},{question:"Can I use Hudi for CDC ingestion and still serve Iceberg readers?",answer:"Yes. Apache XTable translates Hudi table metadata into Iceberg metadata incrementally, without copying or rewriting the underlying Parquet data files. You get Hudi's indexed upserts, delete handling and file sizing on the write path, while Iceberg-only engines and catalogs read the same table through Iceberg metadata."},{question:"Does Iceberg support incremental reads like Hudi?",answer:"Partially. Iceberg supports incremental scans over append snapshots, and Spark can build a changelog view by diffing snapshots, with before/after images as an extra computation. Hudi records commit metadata on every record and logs change data at write time, so incremental and CDC queries read changes directly instead of deriving them, which matters most on update-heavy tables."}]})]})}function h(e={}){const{wrapper:a}={...(0,s.R)(),...e.components};return a?(0,i.jsx)(a,{...e,children:(0,i.jsx)(c,{...e})}):c(e)}}}]);